import json
r=json.load(open('runtime_context.json'))
print('TOP KEYS',list(r))
c=r['context']
print('CONTEXT KEYS',list(c))
for k,v in r.items():
 if k not in ('context','study_schema'): print(k, json.dumps(v))
for k,v in c.items():
 if k not in ('history','knowledge'): print('CONTEXT',k,json.dumps(v)[:25000])
print('HISTORY')
for t in c['history']:
 print(json.dumps({k:v for k,v in t.items() if k"'!='"'validation'}))
 print('VAL', json.dumps({k:v for k,v in t.get('validation',{}).items() if k"'!='"'slices'}))
PY"

